import{_ as r,o,c as e,ag as a}from"./chunks/framework.QfQ7DfGu.js";const c=JSON.parse('{"title":"LA 相关 IP","description":"","frontmatter":{"title":"LA 相关 IP","outline":"deep"},"headers":[],"relativePath":"practice/ip.md","filePath":"practice/ip.md"}'),n={name:"practice/ip.md"};function d(l,t,i,p,s,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="loongarch相关ip" tabindex="-1">LoongArch相关IP <a class="header-anchor" href="#loongarch相关ip" aria-label="Permalink to &quot;LoongArch相关IP&quot;">​</a></h1><h2 id="loongarch64相关的处理器核" tabindex="-1">LoongArch64相关的处理器核 <a class="header-anchor" href="#loongarch64相关的处理器核" aria-label="Permalink to &quot;LoongArch64相关的处理器核&quot;">​</a></h2><h3 id="_1-openc910-loongarch64" tabindex="-1"><strong>1. OpenC910-LoongArch64</strong> <a class="header-anchor" href="#_1-openc910-loongarch64" aria-label="Permalink to &quot;**1. OpenC910-LoongArch64**&quot;">​</a></h3><p>该处理器的概述：<br> 玄铁 C910 是面向嵌入式系统和 SoC 应用领域的 64 位超高性能嵌入式多处理器核，具有出色的性能表<br> 现。 C910 采用了 RISCV 64GC 基本指令集，和平头哥性能增强指令集，主要面向对性能要求严格的高端嵌<br> 入式应用，如人工智能、自动驾驶、移动智能终端、高性能通信、信息安全等等。</p><p>C910MP 采用同构多核架构，支持 2 个 C910 核心。每个 C910 核心采用自主设计的体系结构和微体系<br> 结构，并重点针对性能进行优化，引入 3 发射 8 执行的超标量架构、多通道的数据预取等高性能技术。<br> C910支持实时检测并关断内部空闲功能模块，进一步降低处理器动态功耗。</p><p>OpenC910是3译码、4发射、具有先进的12级流水线，乱序执行的超标量处理器。</p><p><strong>此版本是龙芯实验室将LoongArch64指令集在OpenC910上实现</strong>。</p><table tabindex="0"><thead><tr><th>Features</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>基础整型指令集</td><td>✅​</td><td>暂时不支持LoongArchV1.1</td></tr><tr><td>基础浮点指令集</td><td>✅​</td><td>暂时不支持LoongArchV1.1</td></tr><tr><td>CSR指令</td><td>✅​</td><td>部分CSR寄存器不支持</td></tr><tr><td>IOCSR指令</td><td>✅​</td><td>用于多核之间的支持</td></tr><tr><td>CACOP指令</td><td>❌​</td><td>仅支持写回和无效L1Cache、L2Cache</td></tr><tr><td>TLB维护指令</td><td>✅​</td><td>仅支持invtlb指令，其他的视为空操作</td></tr><tr><td>软件页表遍历指令</td><td>❌​</td><td>目前版本只支持硬件PTW操作</td></tr><tr><td>DBCL指令</td><td>❌​</td><td>目前版本暂时不支持</td></tr><tr><td>LSX</td><td>❌​</td><td>🚧 计划支持中</td></tr><tr><td>LASX</td><td>❌​</td><td>🚧 计划支持中</td></tr><tr><td>LVZ</td><td>❌​</td><td>🚧 计划支持中</td></tr><tr><td>LBT</td><td>❌​</td><td>🚧 计划支持中</td></tr><tr><td>TLB</td><td>✅​</td><td>虚拟48位，物理40位，三级页表</td></tr><tr><td>页面大小</td><td>✅​</td><td>目前只支持4KB，2MB，1GB页</td></tr><tr><td>多核支持</td><td>✅​</td><td>目前配置最大支持4个核心</td></tr></tbody></table><p>仓库在<a href="https://github.com/LoongsonLab/OpenC910-LoongArch64" target="_blank" rel="noreferrer">这里</a></p><p>这是<a href="https://github.com/LoongsonLab/OpenC910-LoongArch64-Linux-Config" target="_blank" rel="noreferrer">相关的SDK</a> 包括Linux kernel的配置，boot以及rootfs等内容。</p><h3 id="_2-labcore-164" tabindex="-1"><strong>2. LabCore-164</strong> <a class="header-anchor" href="#_2-labcore-164" aria-label="Permalink to &quot;**2. LabCore-164**&quot;">​</a></h3><p>Lab-Core-164(单发射，支持LoongArch64)源自于OpenC906，<strong>五级流水线，支持浮点</strong>。 目前已经完成了基本指令集的移植。</p><p>项目代码结构如下：</p><ul><li><strong>design</strong>: 包含基本的设计Verilog文件.</li><li><strong>design/sys</strong>: 用于CPU核的Verilog文件.</li><li><strong>design/sim</strong>: 用于仿真的Verilog文件.</li><li><strong>doc</strong>: 基本文档目录，包括OpenC910的原始设计文档.</li><li><strong>ext</strong>: 包含一些C源码，比如测试样例，还有一些自动生成的Verilog文件.</li><li><strong>ip</strong>: AMD Xilinx 的IP文件，包括Block Design的TCL脚本文件.</li><li><strong>impl/constraints</strong>: 存放所支持开发版的Vivado约束文件.</li><li><strong>impl/work-xlnx</strong>: Vivado工作目录，会在此目录下生成所需文件，包括bitstream文件.</li><li><strong>scripts</strong>: 项目使用的脚本.</li><li><strong>verif/vcs</strong>: Synopsys VCS 仿真环境目录.</li><li><strong>verif/verilator</strong>: Verilator仿真环境目录.</li><li><strong>files.lst</strong>: 项目使用的verilog文件列表.</li><li><strong>Makefile</strong>: make 脚本.</li><li><strong>README.md</strong>: 说明文件.</li></ul><p>仓库在<a href="https://github.com/LoongsonLab/lab-core-164" target="_blank" rel="noreferrer">这里</a></p><h2 id="loonarch32相关的处理器核" tabindex="-1">LoonArch32相关的处理器核 <a class="header-anchor" href="#loonarch32相关的处理器核" aria-label="Permalink to &quot;LoonArch32相关的处理器核&quot;">​</a></h2><h3 id="_1-chiplab平台" tabindex="-1"><strong>1. ChipLab平台</strong> <a class="header-anchor" href="#_1-chiplab平台" aria-label="Permalink to &quot;**1. ChipLab平台**&quot;">​</a></h3><p>Chiplab项目致力于构建基于LoongArch32 Reduced的soc敏捷开发平台。五级流水，32位CPU。</p><p>但是已经流片。</p><p>此项目实现的loongarch32r指令集，未实现浮点指令。</p><p>仓库在<a href="https://gitee.com/loongson-edu/chiplab" target="_blank" rel="noreferrer">这里</a></p><h3 id="_2-openla500" tabindex="-1"><strong>2. OpenLA500</strong> <a class="header-anchor" href="#_2-openla500" aria-label="Permalink to &quot;**2. OpenLA500**&quot;">​</a></h3><p>openLA500是一款实现了龙芯架构32位精简版指令集（loongarch32r）的处理器核。<br> 其结构为单发射五级流水，分为取指、译码、执行、访存、写回五个流水级。<br> 并且含有两路组相连结构的指令和数据cache；32项tlb；以及简易的分支预测器。<br> 此外，处理器核对外为AXI接口，容易集成。</p><p>OpenLA500已经过流片验证，.13工艺下频率为100M，dhrystone，coremark分数分别<br> 为0.78 DMIPS/MHz(指令数有点高)，2.75 coremark/Mhz。软件方面，uboot、linux-5.14、<br> ucore、rt-thread等常用工具及内核已完成对openLA500的适配。</p><p>仓库在<a href="https://gitee.com/loongson-edu/open-la500" target="_blank" rel="noreferrer">这里</a></p><h3 id="_3-争流-处理器" tabindex="-1"><strong>3. “争流”处理器</strong> <a class="header-anchor" href="#_3-争流-处理器" aria-label="Permalink to &quot;**3. “争流”处理器**&quot;">​</a></h3><p>“争流”处理器是一款基于LoongArch指令集32位精简版的乱序超标量通用中央处理器核。</p><p>流水线分为8个流水级: 三个取指级，译码级，重命名级，发射级，寄存器级和执行级。</p><p>使用Spinal HDL开发。</p><p>仓库在<a href="https://gitee.com/liangliang678/ZhengLiu" target="_blank" rel="noreferrer">这里</a></p><h3 id="_4-流云-处理器" tabindex="-1"><strong>4. “流云”处理器</strong> <a class="header-anchor" href="#_4-流云-处理器" aria-label="Permalink to &quot;**4. “流云”处理器**&quot;">​</a></h3><p>流云”处理器是是一款基于LoongArch指令集的单发射7级流水通用中央处理器核。</p><p>本处理器追求高FPGA综合主频和低面积低功耗， 由Spinal HDL提供了高效的描述方式，<br> 既是对简单流水线CPU的探索和回顾， 也是对探索方式的尝试。</p><p>使用Spinal HDL开发。</p><p>仓库在<a href="https://gitee.com/UCAS-Muradil/LiuYun" target="_blank" rel="noreferrer">这里</a></p><h3 id="_5-openla1000" tabindex="-1"><strong>5. OpenLA1000</strong> <a class="header-anchor" href="#_5-openla1000" aria-label="Permalink to &quot;**5. OpenLA1000**&quot;">​</a></h3><p>一个实验性处理器核。</p><p>使用Spinal HDL开发。</p><p>仓库在<a href="https://gitee.com/loongson-edu/open-la1000" target="_blank" rel="noreferrer">这里</a></p>',39)])])}const b=r(n,[["render",d]]);export{c as __pageData,b as default};
